function readUrl() {
  const p = new URLSearchParams(location.search);
  if (p.has("sp")) state.species = new Set(p.get("sp").split(",").filter(c => SPECIES_META[c]));
  if (p.has("sz")) state.sizes = new Set(p.get("sz").split(",").filter(c => SIZE_IDS.includes(c)));
  if (p.has("d")) state.maxDistanceKm = Math.max(0, Math.min(1000, Number(p.get("d")) || 1000));
  if (p.has("rc") && RECENCY_OPTIONS.some(o => o.id === p.get("rc"))) state.recency = p.get("rc");
  if (p.has("v") && ["map", "list", "zones"].includes(p.get("v"))) state.view = p.get("v");
  if (p.has("cm") && COLOR_MODES.some(m => m.id === p.get("cm"))) state.colorMode = p.get("cm");
  if (p.has("c")) state.chartType = p.get("c");
  if (p.get("open") === "1") state.openNow = true;
  if (p.get("ice") === "1") state.iceFishing = true;
  if (p.get("aer") === "1") state.aeratedOnly = true;
  // Validated against what was actually collected, so a stale or hand-typed
  // link cannot leave a filter switched on that nothing can satisfy.
  if (p.has("fac")) pendingFacilities = p.get("fac").split("|").filter(Boolean);
  if (["now", "week"].includes(p.get("cx"))) {
    state.conditions.open = true;
    state.conditions.horizon = p.get("cx");
  }
  if (p.has("home")) {
    const [lat, lon, ...rest] = p.get("home").split(",");
    if (Number.isFinite(Number(lat)) && Number.isFinite(Number(lon))) {
      state.home = { lat: Number(lat), lon: Number(lon), name: rest.join(",") || "Chosen point" };
    }
  }
  return p;
}

