function regulationFor(lake) {
  if (!REGULATIONS) return null;
  return REGULATIONS.lakes[lakeKey(lake)] || null;
}

/* Season parsing lives in js/conditions.js, because a shut season has to
 * suppress the bite score as well as label the popup, and because the
 * year-wrapping case needs a test. */
const seasonOpenOn = (text, when) => Conditions.seasonOpenOn(text, when);

/** True, false, or null when we cannot tell. Null is not "open". */
function lakeOpenNow(lake, when) {
  const reg = regulationFor(lake);
  if (!reg || !reg.season) return null;
  return seasonOpenOn(reg.season.text, when || new Date());
}

/** True when the season is open all winter, false when it is not, null when
 *  we cannot tell. Like "open today", null is kept on the map, never hidden. */
function lakeOpenAllWinter(lake) {
  const reg = regulationFor(lake);
  if (!reg || !reg.season || !Conditions.seasonOpenAllWinter) return null;
  return Conditions.seasonOpenAllWinter(reg.season.text);
}

/** Stated aerated: on ACA's roster or on Alberta's own lake page. A windmill
 *  seen only in a photo does not count, for the reason the README gives. */
function lakeAerated(lake) {
  const d = depthFor(lake);
  return !!(d && d.aerated);
}

